<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class Opportunity extends Model { protected $fillable=['user_id','slug','title','organization','category','opportunity_type','country_name','city','is_remote','summary','description','requirements','benefits','application_url','contact_email','contact_phone','published_at','deadline_at','status','review_note','reviewed_at','reviewed_by']; protected function casts(): array { return ['is_remote'=>'boolean','published_at'=>'datetime','deadline_at'=>'datetime']; } public function owner(): BelongsTo { return $this->belongsTo(User::class,'user_id'); } public function applications(): HasMany { return $this->hasMany(Application::class); } public function savedBy(): HasMany { return $this->hasMany(SavedOpportunity::class); } public function reviewLogs(): HasMany { return $this->hasMany(OpportunityReviewLog::class); } }
